"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71545"],{2525(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.nome_social_diferente_da_conta","status":422,"titulo":"O nome social informado n\xe3o \xe9 o da conta do candidato"},"descricao":{"codigo":"uniplus.selecao.inscricao.nome_social_diferente_da_conta","requisitos":["UNI-REQ-0153","UNI-REQ-0144"],"oQueAconteceu":["Como a regra \xe9 do nome social (UNI-REQ-0153), e n\xe3o do formul\xe1rio, esta recusa\\ntamb\xe9m vale, com o mesmo c\xf3digo, no envio do formul\xe1rio que coleta a escolha do\\nuso do nome social em processo de resultado importado, que n\xe3o tem inscri\xe7\xe3o.\\nNesse caso, onde o texto diz \\"inscri\xe7\xe3o\\", leia \\"o formul\xe1rio da fase\\". Isso \xe9 regra\\nprevista, ainda n\xe3o emitida pela API fora da inscri\xe7\xe3o.","O candidato escolheu usar nome social, e a resposta do nome social \xe9\\ndiferente do nome social cadastrado na conta. O nome social \xe9 dado da\\nconta: a inscri\xe7\xe3o o recebe da conta e n\xe3o o aceita alterado. A compara\xe7\xe3o\\nignora os espa\xe7os nas pontas e os repetidos no meio, mas distingue\\nmai\xfasculas e acentos.","No portal o campo vem travado com o nome social da conta, ent\xe3o esta recusa\\nindica um corpo montado fora da tela, ou um nome social alterado na conta\\nenquanto a inscri\xe7\xe3o estava aberta, com o valor anterior ainda no\\nformul\xe1rio."],"comoResolver":["Envie o nome social exatamente como est\xe1 na conta, ou recarregue a\\ninscri\xe7\xe3o para que o campo traga o valor atual. Para mudar o nome social,\\naltere-o em **Meu perfil**, no menu da conta."],"ondeAparece":["Grava\xe7\xe3o do rascunho da inscri\xe7\xe3o","Envio da inscri\xe7\xe3o do candidato","Envio do formul\xe1rio que coleta a escolha do uso do nome social, em processo de resultado importado (regra prevista, UNI-REQ-0144)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);